"""Tests for datasets generated by data model elements (spectral-model-clp-guide)."""

from __future__ import annotations

import numpy as np
import pytest
import xarray as xr

from glotaran.model.errors import GlotaranUserError
from glotaran.optimization.data import LinkedOptimizationData
from glotaran.optimization.optimization import Optimization
from glotaran.parameter import Parameters
from glotaran.project.scheme import Scheme

TIME = np.arange(0.0, 50.0, 1.0)
SPECTRAL = np.arange(600.0, 701.0, 5.0)
RATE = 0.1


def gaussian(axis: np.ndarray, amplitude: float, location: float, width: float) -> np.ndarray:
    return amplitude * np.exp(-np.log(2) * np.square(2 * (axis - location) / width))


def measured_data() -> xr.Dataset:
    """Noise-free decay of one species whose spectrum is 2 * gaussian(650, 20)."""
    data = np.outer(np.exp(-RATE * TIME), gaussian(SPECTRAL, 2.0, 650.0, 20.0))
    return xr.DataArray(data, coords=[("time", TIME), ("spectral", SPECTRAL)]).to_dataset(
        name="data"
    )


def make_scheme() -> Scheme:
    return Scheme.from_dict(
        {
            "library": {
                "decay": {"type": "kinetic", "rates": {"(s1, s1)": "rates.k1"}},
                "guide": {
                    "type": "spectral-model-clp-guide",
                    "target": "s1",
                    "shapes": {
                        "s1": {
                            "type": "gaussian",
                            "amplitude": "shape.amplitude",
                            "location": "shape.location",
                            "width": "shape.width",
                        }
                    },
                },
            },
            "experiments": {
                "linked": {
                    "datasets": {
                        "measured": {
                            "elements": ["decay"],
                            "activations": {"irf": {"type": "instant", "compartments": {"s1": 1}}},
                        },
                        "guide_data": {"elements": ["guide"], "weights": [{"value": 10.0}]},
                    }
                }
            },
        }
    )


def make_parameters(location: float) -> Parameters:
    return Parameters.from_list(
        [
            ["rates.k1", RATE, {"vary": False}],
            ["shape.amplitude", 2.0, {"vary": False}],
            ["shape.location", location],
            ["shape.width", 20.0, {"vary": False}],
        ]
    )


def make_optimization(scheme: Scheme, parameters: Parameters) -> Optimization:
    scheme._load_data({"measured": measured_data()})
    return Optimization(
        models=list(scheme.experiments.values()),
        parameters=parameters,
        library=scheme.library,
        verbose=False,
        raise_exception=True,
    )


def test_generated_dataset_is_created_on_measured_spectral_axis():
    scheme = make_scheme()
    optimization = make_optimization(scheme, make_parameters(655.0))
    objective = optimization._objectives[0]
    assert isinstance(objective.data, LinkedOptimizationData)

    guide = objective.model.datasets["guide_data"].data
    np.testing.assert_array_equal(guide.spectral, SPECTRAL)
    np.testing.assert_array_equal(guide.time, [0.0])
    np.testing.assert_allclose(guide.data[0], gaussian(SPECTRAL, 2.0, 655.0, 20.0))
    # The scheme's own data model is not modified.
    assert scheme.experiments["linked"].datasets["guide_data"].data is None


def test_generated_data_refresh_matches_full_alignment():
    scheme = make_scheme()
    optimization = make_optimization(scheme, make_parameters(655.0))
    objective = optimization._objectives[0]
    data = objective.data
    assert isinstance(data, LinkedOptimizationData)

    optimization._parameters.get("shape.location").value = 640.0
    objective.calculate()

    guide = data.data["guide_data"]
    np.testing.assert_allclose(guide.generated_data[0], gaussian(SPECTRAL, 2.0, 640.0, 20.0))
    np.testing.assert_allclose(guide.data, 10.0 * guide.generated_data)
    aligned_global_axes = {label: d.global_axis for label, d in data.data.items()}
    _, expected_slices = data.align_data(aligned_global_axes)
    for refreshed, expected in zip(data.data_slices, expected_slices, strict=True):
        np.testing.assert_array_equal(refreshed, expected)


def test_generated_data_parameters_are_optimized():
    """The guide shape location is only recoverable if the guide data are refreshed."""
    scheme = make_scheme()
    result = scheme.optimize(
        make_parameters(655.0), {"measured": measured_data()}, verbose=False, raise_exception=True
    )

    assert result.optimized_parameters.get("shape.location").value == pytest.approx(650.0)
    assert set(result.optimization_results) == {"measured", "guide_data"}


def test_missing_measured_data_is_still_rejected():
    scheme = make_scheme()
    with pytest.raises(GlotaranUserError, match="'measured'"):
        scheme.optimize(make_parameters(655.0), {}, verbose=False)
